$programmeRsc = $programmeRsc.Replace('Weeks 5–9', 'Weeks 5–11').Replace('Weeks 10–18', 'Weeks 12–18')

# The programme record is one JSON value; the original hand-authored suffix
# included three surplus closing tokens that made client hydration fail.
$programmeRsc = $programmeRsc.Substring(0, $programmeRsc.Length - 3)

$css = @'

/* Free taster and staged founding offer */
.taster{display:grid;grid-template-columns:minmax(280px,.82fr) minmax(320px,1.18fr);gap:clamp(2rem,5vw,5rem);align-items:center;background:linear-gradient(135deg,#071525,#0b2137);color:#f8f2e7;border-radius:2px;margin-top:clamp(3rem,7vw,7rem);padding:clamp(1.5rem,4vw,4rem)}
.tasterFlyer,.programmeFlyer{margin:0}.tasterFlyer img,.programmeFlyer img{display:block;width:100%;height:auto;border:1px solid rgba(190,139,61,.58);box-shadow:0 24px 60px rgba(0,0,0,.32)}
.tasterCopy h2{color:#fff;margin:.45rem 0 1rem}.tasterCopy>p{color:#d8dfe5;line-height:1.75}.tasterHighlights{display:grid;gap:.55rem;margin:1.4rem 0;color:#e8c377;font-weight:700}.tasterDays{columns:2;column-gap:2rem;padding-left:1.35rem;margin:1.2rem 0 1.8rem}.tasterDays li{break-inside:avoid;margin:0 0 .65rem;color:#f4efe7}.tasterCopy small{display:block;margin-top:1rem;color:#aebbc7}
.programme{grid-template-columns:minmax(280px,.9fr) minmax(260px,.65fr);align-items:start;gap:clamp(2rem,4vw,4rem)}.programmeFlyer{grid-column:2;grid-row:1}.pricingPanel{grid-column:1/-1;margin-top:1rem}.pricingHeading{text-align:center;max-width:760px;margin:0 auto 2rem}.pricingHeading h3{font-family:Georgia,serif;font-size:clamp(1.8rem,3vw,3rem);margin:.45rem 0;color:#0d1b2a}.pricingHeading>p:last-child{color:#5e6872;line-height:1.7}.stagePricingGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.stagePriceCard{position:relative;display:flex;flex-direction:column;padding:1.45rem;background:#071525;color:#f8f2e7;border:1px solid rgba(190,139,61,.55);min-height:100%}.stagePriceCard h3{font-family:Georgia,serif;font-size:1.45rem;color:#e8c377;margin:.4rem 0 .65rem}.stagePriceCard>p:not(.stageWeeks){color:#cbd3da;line-height:1.6;flex:1}.stageNumber{position:absolute;right:1.2rem;top:1rem;font-family:Georgia,serif;font-size:2rem;color:rgba(232,195,119,.3)}.stageWeeks{font-size:.75rem;letter-spacing:.13em;text-transform:uppercase;color:#e8c377}.stagePrice{display:flex;align-items:baseline;gap:.75rem;margin:1.2rem 0 .2rem}.stagePrice s{color:#99a5af;font-size:1rem}.stagePrice strong{font-family:Georgia,serif;font-size:2.65rem;color:#fff}.stagePriceCard small{color:#e8c377;margin-bottom:1.15rem}.stagePriceCard .primary{margin-top:auto;text-align:center}.launchNote{text-align:center;margin:1.4rem auto 0;max-width:850px;color:#4f5b65}.launchNote strong{color:#9a6823}
@media(max-width:980px){.stagePricingGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.taster{grid-template-columns:1fr}.tasterDays{columns:1}.programme{grid-template-columns:1fr}.programmeFlyer{grid-column:1;grid-row:auto;max-width:520px;margin:0 auto}.pricingPanel{grid-column:1}.stagePricingGrid{grid-template-columns:1fr}}
'@

$html = Get-Content -Raw -LiteralPath $htmlPath
$rsc = Get-Content -Raw -LiteralPath $rscPath
$originalRscLines = $rsc -split "`r?`n"
$oldMainLine = $originalRscLines | Where-Object { $_.StartsWith('1:') } | Select-Object -First 1
$oldProgrammeLine = $originalRscLines | Where-Object { $_.Contains('17:["$","section",null,{"className":"programme section"') } | Select-Object -First 1

if (-not $html.Contains('<section class="starterGuide section">')) { throw 'Starter guide insertion point was not found.' }
if (-not $oldMainLine.Contains('["$","section",null,{"className":"starterGuide section"')) { throw 'RSC starter guide insertion point was not found.' }
if (-not $oldProgrammeLine) { throw 'Existing RSC programme section was not found.' }

$html = $html.Replace('<section class="starterGuide section">', $tasterHtml + '<section class="starterGuide section">')
$html = [regex]::Replace($html, '<section class="programme section" id="programme">.*?</section><section class="cta">', $programmeHtml + '<section class="cta">', [System.Text.RegularExpressions.RegexOptions]::Singleline)

$newMainLine = $oldMainLine.Replace('["$","section",null,{"className":"starterGuide section"', $tasterRsc + ',["$","section",null,{"className":"starterGuide section"')
$programmePrefix = $oldProgrammeLine.Substring(0, $oldProgrammeLine.IndexOf('17:'))
$newProgrammeLine = $programmePrefix + $programmeRsc
$rsc = $rsc.Replace($oldMainLine, $newMainLine).Replace($oldProgrammeLine, $newProgrammeLine)

function Escape-RscLine([string]$line) {
  return $line.Replace('\', '\\').Replace('"', '\"').Replace('&', '\u0026').Replace('<', '\u003c').Replace('>', '\u003e') + '\n'
}

$oldMainEscaped = Escape-RscLine $oldMainLine
$newMainEscaped = Escape-RscLine $newMainLine
$oldProgrammePayload = $oldProgrammeLine.Substring($oldProgrammeLine.IndexOf('17:'))
$oldProgrammeEscaped = Escape-RscLine $oldProgrammePayload
$newProgrammeEscaped = Escape-RscLine $programmeRsc

if (-not $html.Contains($oldMainEscaped)) { throw 'Embedded RSC main payload was not found.' }
if (-not $html.Contains($oldProgrammeEscaped)) { throw 'Embedded RSC programme payload was not found.' }
$html = $html.Replace($oldMainEscaped, $newMainEscaped).Replace($oldProgrammeEscaped, $newProgrammeEscaped)

$existingCss = Get-Content -Raw -LiteralPath $cssPath
if ($existingCss.Contains('/* Free taster and staged founding offer */')) { throw 'Offer styles have already been added.' }

Set-Content -LiteralPath $htmlPath -Value $html -NoNewline
Set-Content -LiteralPath $rscPath -Value $rsc -NoNewline
Add-Content -LiteralPath $cssPath -Value $css -NoNewline
